def L(source, start, duration, gain=1.0, delay=0.0, *, hp=None, lp=None, speed=1.0):
    layer = {'source': SOURCES[source], 'start': start, 'duration': duration,
             'speed': speed, 'gain': gain, 'delay': delay}
    if hp is not None:
        layer['highpass_hz'] = hp
    if lp is not None:
        layer['lowpass_hz'] = lp
    return layer


def V(duration, fade_in, fade_out, rms, *layers, note, envelope='flat'):
    return {'layers': list(layers), 'duration': duration, 'fade_in': fade_in,
            'fade_out': fade_out, 'envelope': envelope, 'target_rms': rms,
            'note': note}


def C(label, category, gain, interval, concurrency, priority, variants, *, note,
      protected=False, pitch=(0.99, 1.01), volumeVariation=0.025, loop=False):
    cue = {'label': label, 'category': category, 'count': len(variants),
           'gain': gain, 'interval': interval, 'concurrency': concurrency,
           'priority': priority, 'pitch': list(pitch),
           'volumeVariation': volumeVariation, 'protected': protected,
           'variants': variants, 'note': note}
    if loop:
        cue.update(loop=True, loop_crossfade=0.5, duration=16, channels=2)
    return cue


